#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file in place."""

import re
import sys
from html.parser import HTMLParser
from pathlib import Path


# Elements whose contents can execute script or otherwise provide an active
# browser execution context.  Removing the complete element is safer than
# trying to rewrite its contents.
DROP_ELEMENTS = {
    "script", "iframe", "object", "embed", "applet", "base", "form",
}

# URL-bearing attributes which must not contain executable schemes.
URL_ATTRIBUTES = {
    "href", "src", "action", "formaction", "cite", "background",
    "poster", "profile", "usemap", "longdesc", "dynsrc", "lowsrc",
    "ping", "xlink:href",
}

# Keep the parser close to the original HTML serialization: only remove the
# dangerous pieces, and retain ordinary start/end tags and text verbatim.
EVENT_ATTRIBUTE = re.compile(r"^on[a-z0-9_:-]+$", re.I)
LEADING_SPACE = re.compile(r"^[\s\ufeff]*")


def dangerous_url(value: str) -> bool:
    """Return true for URL values that can execute script in a browser."""
    normalized = re.sub(r"[\x00-\x20\t\r\n\f]+", "", value).lower()
    return (
        normalized.startswith("javascript:")
        or normalized.startswith("vbscript:")
        or normalized.startswith("data:text/html")
        or normalized.startswith("data:application/xhtml+xml")
        or normalized.startswith("data:image/svg+xml")
    )


class Sanitizer(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=False)
        self.out = []
        self.drop_depth = 0
        self.raw_depth = 0

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        if self.drop_depth:
            if tag_lower in DROP_ELEMENTS:
                self.drop_depth += 1
            return
        if tag_lower in DROP_ELEMENTS:
            self.drop_depth = 1
            return

        kept = []
        for name, value in attrs:
            name_lower = name.lower()
            if EVENT_ATTRIBUTE.match(name_lower):
                continue
            if name_lower in URL_ATTRIBUTES and value is not None and dangerous_url(value):
                continue
            # SVG/MathML namespace attributes can also carry script URLs.
            if name_lower in {"href", "xlink:href"} and value is not None and dangerous_url(value):
                continue
            kept.append((name, value))

        # Re-emit only this tag. Attribute quoting may be normalized by the
        # standard parser, which is explicitly allowed by the task.
        self.out.append("<" + tag)
        for name, value in kept:
            self.out.append(" " + name)
            if value is not None:
                escaped = value.replace("&", "&amp;").replace('"', "&quot;")
                self.out.append('="' + escaped + '"')
        self.out.append(">")

    def handle_startendtag(self, tag, attrs):
        tag_lower = tag.lower()
        if self.drop_depth or tag_lower in DROP_ELEMENTS:
            return
        kept = []
        for name, value in attrs:
            if EVENT_ATTRIBUTE.match(name.lower()):
                continue
            if name.lower() in URL_ATTRIBUTES and value is not None and dangerous_url(value):
                continue
            kept.append((name, value))
        self.out.append("<" + tag)
        for name, value in kept:
            self.out.append(" " + name)
            if value is not None:
                self.out.append('="' + value.replace("&", "&amp;").replace('"', "&quot;") + '"')
        self.out.append("/>")

    def handle_endtag(self, tag):
        if self.drop_depth:
            if tag.lower() in DROP_ELEMENTS:
                self.drop_depth -= 1
            return
        self.out.append("</" + tag + ">")

    def handle_data(self, data):
        if not self.drop_depth:
            self.out.append(data)

    def handle_entityref(self, name):
        if not self.drop_depth:
            self.out.append("&" + name + ";")

    def handle_charref(self, name):
        if not self.drop_depth:
            self.out.append("&#" + name + ";")

    def handle_comment(self, data):
        # HTML comments can contain browser conditional/script tricks; remove
        # comments that contain script-looking content, preserve other comments.
        if not self.drop_depth:
            if re.search(r"(?:<\s*script|javascript\s*:|\bon\w+\s*=)", data, re.I):
                return
            self.out.append("<!--" + data + "-->")

    def handle_decl(self, decl):
        if not self.drop_depth:
            self.out.append("<!" + decl + ">")

    def handle_pi(self, data):
        if not self.drop_depth:
            self.out.append("<?" + data + ">")

    def handle_unknown_decl(self, data):
        if not self.drop_depth:
            self.out.append("<![" + data + "]>")


def sanitize(text: str) -> str:
    parser = Sanitizer()
    parser.feed(text)
    parser.close()
    return "".join(parser.out)


def main() -> int:
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} HTML_FILE", file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    raw = path.read_bytes()
    # Preserve UTF-8 and common legacy encodings as far as possible.
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        text = raw.decode("latin-1")
    result = sanitize(text)
    path.write_bytes(result.encode("utf-8"))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
